if ~exist('src200s','var')
    src200s = sqw('e:\SHARE\Fe\Data\sqw\sqw2024\Fe_ei200_align_sym3.sqw');
end
file = src200s.full_filename %[output:5cf5973d]
[~,fname] = fileparts(file);
w2_00 = cut(src200s,line_proj(),0.04,0.04,[-0.1,0.1],[95,105]);
plot(w2_00);liny; lz 0 1; keep_figure; %[output:3c68608a]

hc = hor_config;
ll = hc.log_level;
hc.log_level = -2;
% recover masks not to draw them again
[cuts2fit200HN,mask_file]  = recover_selected_cuts('cuts2fit200HN','e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits');
% retrieve selected cuts used for further fitting
[HN_FFCutsFits,allJfitfile] = recover_selected_cuts('HN_FFCutsFits','e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts');
%%
Add_binsHN200 = {[-0.1,0.1],[-0.1,0.1],[0,4,200]};

%w2_200a1 = cut(src200s,line_proj([1,1,0],[-1,1,0],'offset',[0.5,1.5,0]),[0.04],Add_bins{:});
%plot(w2_200a1);liny; lz 0 1;keep_figure;
%w2_200a2 = cut(src200s,line_proj([1,1,0],[-1,1,0],'offset',[1.5,0.5,0]),[0.04],Add_bins{:});
%plot(w2_200a2); lz 0 1;keep_figure;

w2_200offH1H0maxFF = cut(src200s,line_proj([1,1,0],[-1,1,0],'offset',[0.5,1.5,0]),0.01,Add_binsHN200{:},SymopReflection('norm',[-1,1,0],'offset',[1,1,0]));
plot(w2_200offH1H0maxFF);liny; lz 0 0.3;keep_figure; %[output:7a8816fe]


w2_200off1H1H0minFF = cut(src200s,line_proj([-1,1,0],[1,1,0],'offset',[1.5,1.5,0]),0.01,Add_binsHN200{:});
plot(w2_200off1H1H0minFF); lz 0 0.3;keep_figure; %[output:16225147]


% w2_200c = cut(src200s,line_proj([1,1,0],[-1,1,0],'offset',[1,1,1]),[0.04],Add_bins{:},SymopReflection('norm',[-1,1,0],'offset',[1,1,0]));
% plot(w2_200c);liny; lz 0 0.3;keep_figure;

%%
bg_200b2 = cut(src200s,line_proj([-1,1,0],[1,1,0],'offset',[2.5,2.5,0]),0.01,Add_binsHN200{:});
plot(bg_200b2);liny; lz 0 0.1;keep_figure; %[output:78390edb]

bg1 = cut(bg_200b2,[1,1.5],[]);
plot(bg1);logy; keep_figure; %[output:63a4396f]
bg_HNEi200 = IX_dataset_1d(bg1);
[~,bg_HNEi200] = fit_IXDsBg_helper(bg_HNEi200,[52,96],true,'g'); %[output:98eb86aa] %[output:8de8aac5]

%%
%w2nbg = repmat(sqw,1,2);
%w2nbg(1) = w2_200offH1H0maxFF - replicate(bg1,w2_200offH1H0maxFF);
%w2nbg(1) = cut(w2nbg(1),[-0.5,0.02,1.5],[0,4,200]);
%plot(w2nbg(1));liny; lz 0 0.1;keep_figure;

%w2nbg(2) = w2_200off1H1H0minFF - replicate(bg1,w2_200off1H1H0minFF);
%w2nbg(2) = cut(w2nbg(2),[-1,0.02,2],[0,4,200]);
%plot(w2nbg(2));liny; lz 0 0.1;keep_figure;


w2nbg(1) = w2_200offH1H0maxFF - sqw_eval(w2_200offH1H0maxFF,@linterp_bg,bg_HNEi200);
%w2nbg(1) = cut(w2nbg(1),[-0.5,0.02,1.5],[0,4,200]);
plot(w2nbg(1));liny; lz 0 0.1;keep_figure; %[output:3e78e52c]

w2nbg(2) = w2_200off1H1H0minFF - sqw_eval(w2_200off1H1H0minFF,@linterp_bg,bg_HNEi200);
%w2nbg(2) = cut(w2nbg(2),[-1,0.02,2],[0,4,200]);
plot(w2nbg(2));liny; lz 0 0.1;keep_figure; %[output:2911d6c9]


